package dev.harpia.target.javaspring;

import static org.assertj.core.api.Assertions.assertThat;

import dev.harpia.CompileRequest;
import dev.harpia.CompileResult;
import dev.harpia.HarpiaCompiler;
import java.nio.file.Path;
import java.util.SortedMap;
import org.junit.jupiter.api.Test;

/**
 * The persistence vertical: {@code required}, {@code unique}, {@code generated} and {@code default}
 * must reach the entity, the schema and the repository consistently, because
 * {@code ddl-auto: validate} turns any disagreement into a startup failure.
 */
class PersistenceEmitterTest {

    private static final String ENTITY =
            "src/main/java/com/example/customer/domain/Customer.java";
    private static final String REPOSITORY =
            "src/main/java/com/example/customer/repository/CustomerRepository.java";

    @Test
    void theEntityCarriesEveryDataConstraintDeclaredInHarpia() {
        String entity = files().get(ENTITY);

        assertThat(entity)
                .contains("package com.example.customer.domain;")
                .contains("@Entity")
                .contains("@Table(name = \"customer\")")
                .contains("@Id")
                .contains("@GeneratedValue(strategy = GenerationType.UUID)")
                .contains("@NotBlank")
                .contains("@Email")
                .contains("@Column(name = \"id\", nullable = false, updatable = false)")
                .contains("@Column(name = \"name\", nullable = false, length = 255)")
                .contains("@Column(name = \"email\", nullable = false, unique = true, length = 320)")
                .contains("private UUID id;")
                .contains("public Customer() {");
    }

    @Test
    void aHarpiaDefaultBecomesAnApplicationDefaultNotADatabaseDefault() {
        assertThat(files().get(ENTITY)).contains("private Boolean active = true;");
        assertThat(files().get(MigrationEmitter.PATH))
                .contains("active boolean NOT NULL")
                .doesNotContain("DEFAULT");
    }

    @Test
    void theMigrationMatchesTheEntityColumnForColumn() {
        assertThat(files().get(MigrationEmitter.PATH))
                .startsWith("-- Generated by Harpia. Do not edit.")
                .contains("CREATE TABLE customer (")
                .contains("id uuid NOT NULL,")
                .contains("name varchar(255) NOT NULL,")
                .contains("email varchar(320) NOT NULL,")
                .contains("CONSTRAINT pk_customer PRIMARY KEY (id),")
                .contains("CONSTRAINT uq_customer_email UNIQUE (email)")
                .endsWith(");\n");
    }

    @Test
    void theRepositoryIsAPortAndNothingMore() {
        assertThat(files().get(REPOSITORY))
                .contains("import com.example.customer.domain.Customer;")
                .contains("public interface CustomerRepository extends JpaRepository<Customer, UUID> {")
                .doesNotContain("existsBy");
    }

    @Test
    void aProjectWithoutEntitiesEmitsNoSchema() {
        CompileResult result = new HarpiaCompiler().compile(
                new CompileRequest(Path.of("examples/business-logic/pricing")));

        assertThat(result.tree().orElseThrow().files())
                .doesNotContainKey(MigrationEmitter.PATH);
    }

    private static SortedMap<String, String> files() {
        CompileResult result = new HarpiaCompiler().compile(
                new CompileRequest(Path.of("examples/customer")));
        assertThat(result.diagnostics()).isEmpty();
        return result.tree().orElseThrow().files();
    }
}
